UPDATE group_data_package_phone SET status=2,claimed_task_id=#{request.taskId},claimed_execution_seq=#{request.executionSeq},allocation_version=allocation_version+1,updated_at=#{now}
 WHERE package_id=#{request.packageId} AND generation=#{request.generation} AND status=1 AND claimed_task_id IS NULL
 AND id IN #{id}

UPDATE group_data_package_phone SET status=#{target},updated_at=#{now}
 ,claimed_task_id=NULL,claimed_execution_seq=NULL
 WHERE status=#{expected} AND (

 (id=#{row.id} AND claimed_task_id=#{row.claimedTaskId} AND claimed_execution_seq=#{row.claimedExecutionSeq} AND allocation_version=#{row.allocationVersion})
 )
